<?php
 namespace Pterodactyl\Services\Dezerx\Ai; use Pterodactyl\Models\User; use Illuminate\Contracts\Cache\Lock; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\RateLimiter; class Runs { private const KEEP_MINUTES = 30; public const SLOTS = 4; public static function limiterKey(User $user): string { return 'dezerx-ai:' . $user->id; } public static function claim(User $user): bool { $limit = Ai::limit(); return RateLimiter::attempt(self::limiterKey($user), $limit['messages'], static fn () => true, $limit['minutes'] * 60) !== false; } public static function allowance(User $user): array { $limit = Ai::limit(); $key = self::limiterKey($user); return [...$limit, 'remaining' => max(0, RateLimiter::remaining($key, $limit['messages'])), 'resetsIn' => RateLimiter::availableIn($key)]; } public static function slot(int $seconds): ?Lock { foreach (range(1, self::SLOTS) as $slot) { $lock = Cache::lock('dezerx:ai:slot:' . $slot, $seconds); if ($lock->get()) { return $lock; } } return null; } public static function begin(string $run, User $user): void { Cache::put(self::activeKey($user), $run, now()->addMinutes(self::KEEP_MINUTES)); } public static function stop(string $run, User $user): void { Cache::put(self::key($run, $user), true, now()->addMinutes(self::KEEP_MINUTES)); } public static function stopping(string $run, User $user): bool { if ($run === '') { return false; } if (Cache::get(self::key($run, $user)) === true) { return true; } $active = Cache::get(self::activeKey($user)); return is_string($active) && $active !== $run; } public static function forget(string $run, User $user): void { Cache::forget(self::key($run, $user)); if (Cache::get(self::activeKey($user)) === $run) { Cache::forget(self::activeKey($user)); } } private static function key(string $run, User $user): string { return 'dezerx:ai:stop:' . $user->id . ':' . $run; } private static function activeKey(User $user): string { return 'dezerx:ai:active:' . $user->id; } } 